parts.text:
{
  "translations": [
    {
      "id": "u42197",
      "vi": "Từ chối giao dịch"
    },
    {
      "id": "u56462",
      "vi": "Giao dịch bạn đề xuất với ⟦1⟧ đã bị từ chối."
    },
    {
      "id": "u34292",
      "vi": "Đã hủy giao dịch thành công."
    },
    {
      "id": "u22864",
      "vi": "Kỳ chuyển nhượng hiện đang đóng"
    },
    {
      "id": "u10552",
      "vi": "Khối giao dịch"
    },
    {
      "id": "u00307",
      "vi": "Các giải đấu trực tuyến hiện không khả dụng"
    },
    {
      "id": "u32769",
      "vi": "Danh sách đội hình duy nhất:"
    },
    {
      "id": "u47048",
      "vi": "Cho phép mỗi thành viên có các cầu thủ trùng lặp trong đội hình. Nếu Danh sách đội hình duy nhất bị tắt, sẽ không thể thực hiện giao dịch hoặc draft cho giải đấu này."
    },
    {
      "id": "u31940",
      "vi": "Tham gia: ⟦1⟧"
    },
    {
      "id": "u10100",
      "vi": "Xem chỉ số cầu thủ"
    },
    {
      "id": "u52438",
      "vi": "Cầu thủ này không còn là thành viên của giải đấu này."
    },
    {
      "id": "u57849",
      "vi": "Blog GM"
    },
    {
      "id": "u50829",
      "vi": "Cầu thủ này không còn là thành viên của giải đấu."
    },
    {
      "id": "u18940",
      "vi": "Lỗi tải dữ liệu chỉ số cầu thủ"
    },
    {
      "id": "u09693",
      "vi": "Lỗi tải dữ liệu nhóm chỉ số cầu thủ"
    },
    {
      "id": "u46051",
      "vi": "Xem chỉ số thành viên giải đấu"
    },
    {
      "id": "u13099",
      "vi": "Xem lời mời tham gia giải đấu"
    },
    {
      "id": "u14002",
      "vi": "EA Locker"
    },
    {
      "id": "u32821",
      "vi": "Không thể tham gia trận đấu, vui lòng thử lại sau."
    },
    {
      "id": "u05405",
      "vi": "Không có phiên đấu nào đáp ứng tiêu chí của bạn. Bạn có muốn tạo phiên đấu riêng không?"
    },
    {
      "id": "u17008",
      "vi": "Phiên đấu này hiện không còn khả dụng."
    },
    {
      "id": "u35318",
      "vi": "Không có phiên đấu nào đáp ứng tiêu chí của bạn. Bạn có muốn điều chỉnh tìm kiếm hoặc tạo phiên đấu riêng không?"
    },
    {
      "id": "u49997",
      "vi": "Đang tìm kiếm các phiên đấu khả dụng..."
    },
    {
      "id": "u28240",
      "vi": "Bật"
    },
    {
      "id": "u70239",
      "vi": "Phương tiện của ⟦1⟧"
    },
    {
      "id": "u36766",
      "vi": "Hướng dẫn kênh"
    },
    {
      "id": "u60256",
      "vi": "Xác nhận bộ lọc"
    },
    {
      "id": "u35651",
      "vi": "Đang xem"
    },
    {
      "id": "u37312",
      "vi": "Đi đến hướng dẫn kênh"
    },
    {
      "id": "u57363",
      "vi": "Hình ảnh này hiện không khả dụng. Vui lòng thử lại sau."
    },
    {
      "id": "u54957",
      "vi": "Phương tiện"
    },
    {
      "id": "u16153",
      "vi": "Không có kênh nào khả dụng. Vui lòng thử lại sau."
    },
    {
      "id": "u10898",
      "vi": "Hiện không có nội dung khả dụng để xem."
    },
    {
      "id": "u08949",
      "vi": "Cuộn bài viết"
    },
    {
      "id": "u38048",
      "vi": "Tìm kiếm nội dung thất bại. Vui lòng thử lại."
    },
    {
      "id": "u44886",
      "vi": "Cài đặt On Demand"
    },
    {
      "id": "u12052",
      "vi": "Tải bài viết thất bại. Vui lòng thử lại sau."
    },
    {
      "id": "u70270",
      "vi": "On Demand"
    },
    {
      "id": "u24906",
      "vi": "Loại nội dung này không thể xem trong On Demand."
    },
    {
      "id": "u56802",
      "vi": "Người dùng này không có nội dung nào khả dụng để xem."
    },
    {
      "id": "u48139",
      "vi": "Xem phương tiện của người dùng"
    },
    {
      "id": "u16806",
      "vi": "Xem phương tiện đã tải lên của người dùng"
    },
    {
      "id": "u59670",
      "vi": "Xem bài viết"
    },
    {
      "id": "u35134",
      "vi": "Xem kênh"
    },
    {
      "id": "u52049",
      "vi": "Đã xảy ra lỗi không mong muốn khi cố gắng truy xuất thông tin Online Pass. Nếu sự cố vẫn tiếp diễn, vui lòng liên hệ bộ phận Hỗ trợ khách hàng của EA."
    },
    {
      "id": "u41406",
      "vi": "Kích hoạt Online Pass để truy cập tất cả các tính năng trực tuyến. Mã KHÔNG phân biệt chữ hoa chữ thường và KHÔNG yêu cầu dấu gạch nối."
    },
    {
      "id": "u62245",
      "vi": "Nhập mã Online Pass"
    },
    {
      "id": "u60381",
      "vi": "Mã bạn đã nhập không hợp lệ."
    },
    {
      "id": "u43554",
      "vi": "Mã bạn đã nhập đã được sử dụng."
    },
    {
      "id": "u34522",
      "vi": "Online Pass không khớp với khu vực được chỉ định trong tài khoản Sony Entertainment Network của bạn. Bạn sẽ không thể chơi trực tuyến."
    }
  ]
}

{
  "translations": [
    {
      "id": "u22220",
      "vi": "Đang truy xuất nội dung từ máy chủ EA. Vui lòng chờ..."
    },
    {
      "id": "u39314",
      "vi": "Hiện không thể truy xuất nội dung từ máy chủ EA. Vui lòng thử lại sau."
    },
    {
      "id": "u63216",
      "vi": "Không thể truy xuất nội dung từ máy chủ EA kịp thời. Vui lòng thử lại sau."
    },
    {
      "id": "u45131",
      "vi": "Hiện không thể bắt đầu phiên bản dùng thử miễn phí. Vui lòng thử lại sau."
    },
    {
      "id": "u58368",
      "vi": "Phiên bản dùng thử miễn phí của bạn đã bắt đầu thành công. Khi thời hạn dùng thử kết thúc, bạn sẽ cần đổi mã sử dụng một lần (có trong tờ hướng dẫn đi kèm bao bì trò chơi) hoặc mua quyền truy cập để tiếp tục sử dụng các tính năng trực tuyến cao cấp."
    },
    {
      "id": "u01477",
      "vi": "Chơi đội trực tuyến"
    },
    {
      "id": "u20919",
      "vi": "Không thể truy xuất Avatar của bạn, vui lòng thử lại."
    },
    {
      "id": "u00230",
      "vi": "Phòng chờ"
    },
    {
      "id": "u04934",
      "vi": "Cần có bản cập nhật cho tựa game này trước khi bạn có thể truy cập bất kỳ tính năng trực tuyến nào."
    },
    {
      "id": "u69720",
      "vi": "Đăng nhập bị gián đoạn vì đã có phiên bản mới của tệp cập nhật được tải xuống."
    },
    {
      "id": "u28040",
      "vi": "Đăng nhập bị gián đoạn vì phần mềm hệ thống của người dùng đã lỗi thời."
    },
    {
      "id": "u58252",
      "vi": "Đăng nhập bị gián đoạn vì phần mềm hệ thống của người dùng đã lỗi thời đối với tựa game này."
    },
    {
      "id": "u51295",
      "vi": "Không thể kết nối với máy chủ."
    },
    {
      "id": "u29772",
      "vi": "Tải xuống danh sách cầu thủ trực tuyến"
    },
    {
      "id": "u11569",
      "vi": "Cài đặt trực tuyến"
    },
    {
      "id": "u51784",
      "vi": "Mở phiên chơi cho công khai"
    },
    {
      "id": "u68518",
      "vi": "Bạn có chắc chắn muốn công khai phiên chơi này không?"
    },
    {
      "id": "u02493",
      "vi": "Đối thủ đã rời khỏi trận đấu."
    },
    {
      "id": "u27079",
      "vi": "Đối thủ: ⟦1⟧"
    },
    {
      "id": "u70372",
      "vi": "Đối thủ ngắt kết nối"
    },
    {
      "id": "u25113",
      "vi": "Đối thủ đã thoát"
    },
    {
      "id": "u45082",
      "vi": "Tùy chọn"
    },
    {
      "id": "u46498",
      "vi": "Bạn sẽ không thể chơi trực tuyến trừ khi tạo Tài khoản EA. Bạn có chắc chắn muốn hủy không?"
    },
    {
      "id": "u15094",
      "vi": "Chọn GỬI để tạo Tài khoản EA của bạn."
    },
    {
      "id": "u28222",
      "vi": "Cảm ơn bạn đã tạo Tài khoản EA! Đừng quên Địa chỉ Email và Mật khẩu Tài khoản EA của bạn. Chúng cần thiết để truy cập các tính năng trực tuyến trong các trò chơi của EA và nội dung cụ thể của trò chơi trên EASPORTS.COM."
    },
    {
      "id": "u09660",
      "vi": "Nâng cấp tài khoản EA"
    },
    {
      "id": "u28360",
      "vi": "Yêu cầu xác nhận tài khoản"
    },
    {
      "id": "u00589",
      "vi": "Nhập mật khẩu đã sử dụng khi bạn tạo tài khoản, hoặc nhập địa chỉ email và mật khẩu mới ngay bây giờ."
    },
    {
      "id": "u32523",
      "vi": "Địa chỉ Email và Tài khoản EA mà bạn đang cố liên kết hiện đang chờ sự đồng ý để chơi trực tuyến. Vui lòng thử lại sau hoặc tạo Tài khoản EA mới bằng Địa chỉ Email khác."
    },
    {
      "id": "u15612",
      "vi": "Địa chỉ email của bạn đã bị hủy. Bạn sắp tạo một Tài khoản EA có quyền truy cập hạn chế. Chủ sở hữu tài khoản hạn chế có thể chơi trò chơi, nhưng không thể sử dụng các tính năng mạng xã hội."
    },
    {
      "id": "u58928",
      "vi": "Bạn phải yêu cầu sự đồng ý của người lớn để chơi trực tuyến. Bạn thực sự muốn hủy bỏ sao?"
    },
    {
      "id": "u25522",
      "vi": "Tài khoản của bạn đã bị vô hiệu hóa. Vui lòng liên hệ bộ phận hỗ trợ khách hàng của EA.⟦1⟧"
    },
    {
      "id": "u03855",
      "vi": "Nhập địa chỉ email bạn muốn liên kết với Tài khoản EA của mình."
    },
    {
      "id": "u59384",
      "vi": "Để được hỗ trợ đặt lại mật khẩu, vui lòng cung cấp địa chỉ email của cha mẹ hoặc người giám hộ.⟦1⟧"
    },
    {
      "id": "u10995",
      "vi": "Nhập địa chỉ email đã sử dụng khi bạn tạo tài khoản. Nếu địa chỉ email của bạn đã thay đổi, bạn có thể nhập địa chỉ mới. Thông tin xác minh tài khoản của bạn sẽ chỉ được gửi đến địa chỉ email này."
    },
    {
      "id": "u36204",
      "vi": "Một thông báo qua email đã được gửi đến địa chỉ email bạn đã nhập, cho biết bạn quan tâm đến việc tạo Tài khoản EA. Vui lòng yêu cầu người nhận phê duyệt yêu cầu bằng cách xem xét email được gửi."
    },
    {
      "id": "u32193",
      "vi": "Thông tin thêm về việc tạo Tài khoản EA."
    },
    {
      "id": "u41073",
      "vi": "Địa chỉ email bạn đã nhập hiện không được liên kết với bất kỳ Tài khoản EA nào đang tồn tại."
    }
  ]
}

{
  "translations": [
    {
      "id": "u14149",
      "vi": "Nhập mật khẩu bạn muốn liên kết với Tài khoản EA. Mật khẩu phải có độ dài từ 8 đến 16 ký tự, bao gồm chữ hoa, chữ thường và chữ số."
    },
    {
      "id": "u67622",
      "vi": "Nhập mật khẩu. Mật khẩu phải có độ dài từ 8 đến 16 ký tự, bao gồm chữ hoa, chữ thường và chữ số."
    },
    {
      "id": "u10628",
      "vi": "Nhập mật khẩu đã sử dụng khi tạo tài khoản, hoặc nhập mật khẩu mới nếu bạn đã thay đổi địa chỉ email."
    },
    {
      "id": "u45237",
      "vi": "Địa chỉ email của bạn đã bị hủy. Để được hỗ trợ khôi phục mật khẩu, vui lòng cung cấp địa chỉ email của cha mẹ hoặc người giám hộ.⟦1⟧⟦2⟧Bạn sắp tạo một Tài khoản EA với quyền truy cập hạn chế. Chủ sở hữu tài khoản hạn chế có thể chơi trò chơi nhưng không thể sử dụng các tính năng mạng xã hội của ứng dụng EA."
    },
    {
      "id": "u15633",
      "vi": "Quản lý Tài khoản EA"
    },
    {
      "id": "u09254",
      "vi": "Cập nhật Tài khoản EA"
    },
    {
      "id": "u09494",
      "vi": "Tài khoản của bạn đã được cập nhật với email và mật khẩu mới. Bạn cũng sẽ nhận được một email xác nhận."
    },
    {
      "id": "u01337",
      "vi": "Cập nhật Địa chỉ Email/ Mật khẩu"
    },
    {
      "id": "u01991",
      "vi": "Cập nhật Mật khẩu"
    },
    {
      "id": "u66140",
      "vi": "Cập nhật Mật khẩu cho Tài khoản EA của bạn."
    },
    {
      "id": "u43757",
      "vi": "Cập nhật Địa chỉ Email/ Mật khẩu của Cha mẹ"
    },
    {
      "id": "u58809",
      "vi": "Cập nhật Địa chỉ Email và/hoặc Mật khẩu của Cha mẹ cho Tài khoản EA của bạn."
    },
    {
      "id": "u38315",
      "vi": "Bây giờ bạn có thể nâng cấp lên Tài khoản EA đầy đủ. Vui lòng điền vào biểu mẫu bên dưới để hoàn tất quá trình nâng cấp."
    },
    {
      "id": "u53667",
      "vi": "Đã xảy ra lỗi khi nâng cấp tài khoản. Vui lòng thử lại."
    },
    {
      "id": "u69363",
      "vi": "Tài khoản của bạn đã được nâng cấp thành công."
    },
    {
      "id": "u41565",
      "vi": "Địa chỉ email của cha mẹ"
    },
    {
      "id": "u28209",
      "vi": "Để được hỗ trợ khôi phục mật khẩu, vui lòng cung cấp địa chỉ email của cha mẹ hoặc người giám hộ. Địa chỉ email của bạn đã bị hủy. Bạn sắp tạo một Tài khoản EA với quyền truy cập hạn chế. Chủ sở hữu tài khoản hạn chế có thể chơi trò chơi nhưng không thể sử dụng các tính năng mạng xã hội."
    },
    {
      "id": "u20179",
      "vi": "Tiếp tục"
    },
    {
      "id": "u51317",
      "vi": "Thay trang phục"
    },
    {
      "id": "u51305",
      "vi": "Đổi đội"
    },
    {
      "id": "u61161",
      "vi": "Cộng đồng Chơi Đội trực tuyến"
    },
    {
      "id": "u09596",
      "vi": "Tạo trận đấu"
    },
    {
      "id": "u38191",
      "vi": "Chào mừng đến với Chơi Đội trực tuyến.⟦1⟧⟦2⟧Tại đây bạn có thể tham gia vào các trận đấu với tư cách thành viên của một đội. Đội trưởng có thể chọn đội và thay đổi đội hình, trong khi các cầu thủ khác có thể chọn vị trí của mình trong trận đấu.⟦3⟧⟦4⟧Với tư cách là cầu thủ, bạn nên chọn một đội trước khi Đội trưởng của cả hai đội chuyển sang bước tiếp theo.⟦5⟧⟦6⟧Để tiếp tục tính năng này, Đội trưởng các đội cần đảm bảo đội của mình đã sẵn sàng."
    },
    {
      "id": "u59225",
      "vi": "Các phiên chơi Chơi Đội trực tuyến khả dụng: ⟦1⟧"
    },
    {
      "id": "u48156",
      "vi": "Các trận đấu Câu lạc bộ đang diễn ra: ⟦1⟧"
    },
    {
      "id": "u45704",
      "vi": "Có vẻ như một người chơi khác đang ngắt kết nối, vui lòng chờ trong khi chúng tôi cấu hình lại phiên chơi và thử lại thao tác."
    },
    {
      "id": "u27490",
      "vi": "Chọn đội hình"
    },
    {
      "id": "u51161",
      "vi": "Khóa vị trí"
    },
    {
      "id": "u00402",
      "vi": "Bạn đã mất kết nối với những người chơi khác."
    },
