    {
      "id": "u01776",
      "vi": "Bạn đã mở khóa trận đấu đặc biệt này!"
    },
    {
      "id": "u30475",
      "vi": "Là một hậu vệ cánh thiên về tấn công với những quả tạt cực bén và khả năng kiến tạo nhạy bén, Alexander-Arnold 22 tuổi đã giành được nhiều danh hiệu và giải thưởng — bao gồm chức vô địch Premier League và UEFA Champions League."
    },
    {
      "id": "u16842",
      "vi": "Là một trong những hậu vệ cánh tấn công hay nhất trong lịch sử, Roberto Carlos đã làm nức lòng người hâm mộ ở cả cấp câu lạc bộ lẫn đội tuyển quốc gia. Những cú đá phạt mang tính biểu tượng của anh đã vượt xa khuôn khổ trò chơi, đưa anh trở thành một trong những cầu thủ bóng đá thành công nhất mọi thời đại."
    },
    {
      "id": "u22055",
      "vi": "Nổi tiếng với tốc độ, khả năng rê bóng và dứt điểm, 'Cậu bé vàng' năm 2019 đã góp công lớn đưa Benfica đến chức vô địch Primeira Liga trước khi gia nhập Atlético de Madrid vào năm 2019."
    },
    {
      "id": "u59231",
      "vi": "Là trụ cột tại giải đấu hàng đầu nước Ý trong phần lớn sự nghiệp chuyên nghiệp của mình, Nakata là một tiền vệ sáng tạo với tầm nhìn chuyền bóng đáng kinh ngạc và khả năng xuất hiện bất ngờ trong vòng cấm với những pha xâm nhập dứt điểm chuẩn xác."
    },
    {
      "id": "u37194",
      "vi": "Võ sĩ giành huy chương vàng Olympic và hai lần vô địch quyền anh hạng nặng thế giới Anthony Joshua bước từ võ đài sang sân cỏ bóng đá mini."
    },
    {
      "id": "u69057",
      "vi": "Một tài năng phong cách, ranh mãnh, đầy cá tính với tinh thần cạnh tranh mãnh liệt, cách tiếp cận trận đấu của Cantona hoàn toàn độc nhất vô nhị tại Anh. Với bốn chức vô địch Premier League, hai FA Cup và 73 bàn thắng, tầm ảnh hưởng của anh vẫn còn đậm nét cho đến ngày nay."
    },
    {
      "id": "u11860",
      "vi": "DJ, nhạc sĩ, nhà sản xuất âm nhạc từng giành giải Grammy và là cổ động viên của Arsenal F.C., Diplo, bước từ phòng thu âm sang sân cỏ bóng đá mini."
    },
    {
      "id": "u53080",
      "vi": "Nhà vô địch Super Bowl và cầu thủ xuất sắc nhất (MVP) NFL Patrick Mahomes bước từ sân bóng bầu dục sang sân cỏ bóng đá mini."
    },
    {
      "id": "u22664",
      "vi": "Hai lần đoạt danh hiệu MVP NBA Giannis Antetokounmpo tham gia sân cỏ bóng đá mini để thể hiện kỹ năng bóng đá của mình."
    },
    {
      "id": "u46425",
      "vi": "Ngôi sao từng giành giải Grammy Dua Lipa bước từ phòng thu âm sang sân cỏ bóng đá mini."
    },
    {
      "id": "u49124",
      "vi": "Là một trong những tiền đạo vĩ đại nhất lịch sử Premier League, khả năng dứt điểm thanh thoát nhưng vô cùng chết người đã giúp Henry bốn lần giành Chiếc giày vàng trong tám năm khoác áo Arsenal."
    },
    {
      "id": "u05096",
      "vi": "Kết hợp khả năng ghi bàn đáng kinh ngạc cùng thể hình ấn tượng, Drogba đã giành bốn chức vô địch Premier League, bốn FA Cup và một danh hiệu UEFA Champions League để củng cố vị thế huyền thoại Chelsea của mình."
    }
  ]
}

