      "vi": "Hãy nhớ rằng, đôi khi cách tốt nhất để tiến lên là chuyền ngang, ⟦1⟧ vì vậy hãy kiên nhẫn và dựa vào sự hỗ trợ từ đồng đội."
    },
    {
      "id": "u57194",
      "vi": "Hãy giữ bóng trên mặt đất và luân chuyển bóng ⟦1⟧ để tạo ra cơ hội ghi bàn."
    },
    {
      "id": "u29500",
      "vi": "Quay lại trận đấu và tận hưởng thôi!"
    },
    {
      "id": "u67212",
      "vi": "Để thực hiện những pha sút xa và chính xác, cần có hướng và tốc độ phù hợp."
    },
    {
      "id": "u33055",
      "vi": "Nếu cầu thủ của bạn đang di chuyển ngược hướng với ý định ⟦1⟧ chuyền hoặc sút, cậu ấy sẽ không đủ lực cho các pha bóng dài."
    },
    {
      "id": "u10103",
      "vi": "Nếu cầu thủ di chuyển quá chậm khi sút, cú sút sẽ ⟦1⟧ quá yếu, khiến thủ môn dễ dàng cản phá."
    },
    {
      "id": "u39426",
      "vi": "Để thực hiện các pha bóng dài và chính xác, cầu thủ cần ⟦1⟧ có hướng chuẩn xác cũng như di chuyển với tốc độ đủ lớn."
    },
    {
      "id": "u68812",
      "vi": "Quay lại trận đấu thôi, và hãy nhớ - hướng và chuyển động của ⟦1⟧ cầu thủ là yếu tố cốt lõi khi thực hiện các đường chuyền dài và cú sút mạnh."
    },
    {
      "id": "u12954",
      "vi": "Giành lại quyền kiểm soát bóng đôi khi rất khó khăn."
    },
    {
      "id": "u55788",
      "vi": "Dưới đây là một vài mẹo giúp bạn cải thiện khả năng phòng ngự."
    },
    {
      "id": "u57978",
      "vi": "Đối thủ có thể đưa bóng đi bất kỳ hướng nào, vì vậy phương án tốt nhất ⟦1⟧ là chặn hướng tấn công trực diện nhất về phía khung thành của bạn."
    },
    {
      "id": "u27731",
      "vi": "Khi phòng ngự, hãy cố gắng đưa cầu thủ của bạn vào vị trí giữa bóng và khung thành."
    },
    {
      "id": "u11249",
      "vi": "Hệ thống hỗ trợ phòng ngự sẽ hiển thị một điểm đánh dấu trên sân ⟦1⟧ để giúp bạn dẫn dắt cầu thủ vào đúng vị trí."
    },
    {
      "id": "u54033",
      "vi": "Di chuyển cầu thủ đến vị trí đánh dấu để chặn tiền đạo đối phương."
    },
    {
      "id": "u59591",
      "vi": "Nếu cầu thủ của bạn ở quá xa, bạn có thể ⟦1⟧ đổi sang cầu thủ khác gần vị trí đánh dấu hơn."
    },
    {
      "id": "u30187",
      "vi": "Hãy nhớ, khi phòng ngự, hãy đứng giữa đối thủ và khung thành để giành lại quyền kiểm soát bóng, nhờ đó bạn có thể bắt đầu đợt tấn công của riêng mình."
    },
    {
      "id": "u13338",
      "vi": "Quay lại sân cỏ và tận hưởng trận đấu thôi!"
    },
    {
      "id": "u28373",
      "vi": "Khi phòng ngự, lao lên phía trước ⟦1⟧ có thể tạo lợi thế cho đối thủ."
    },
    {
      "id": "u56267",
      "vi": "Thay vào đó, khi muốn giành lại bóng, hãy sử dụng kỹ thuật Jockey để ⟦1⟧ hạ thấp trọng tâm và đổi hướng nhanh chóng trong khi vẫn bám sát đối thủ."
    },
    {
      "id": "u53524",
      "vi": "Jockey cho phép cầu thủ của bạn đối mặt trực diện với đối thủ,"
    },
    {
      "id": "u13550",
      "vi": "giúp dễ dàng cướp bóng ⟦1⟧ từ chân đối phương khi có cơ hội rõ ràng."
    },
    {
      "id": "u30376",
      "vi": "Hãy nhớ, khi cố gắng giành lại bóng, hãy dùng Jockey để ⟦1⟧ làm chậm nhịp độ đối thủ và giảm các phương án tấn công của họ."
    },
    {
      "id": "u57482",
      "vi": "Quay lại sân cỏ và thử ngay thôi!"
    },
    {
      "id": "u45628",
      "vi": "Việt vị là lỗi rất thường gặp."
    },
    {
      "id": "u00448",
      "vi": "Ban đầu có thể hơi khó hiểu, nhưng đừng ⟦1⟧ lo lắng, nó không phức tạp như bạn nghĩ đâu."
    },
    {
      "id": "u36681",
      "vi": "Hãy cùng xem nhé."
    }
  ]
}

