{
  "translations": [
    {
      "id": "u53760",
      "vi": "Mở khóa thêm các ô PlayStyle/PlayStyle+ bằng cách nâng cấp cấp độ Phát triển Cầu thủ. Kiếm XP bằng cách chơi Clubs, so tài trong các trận Drop-in, hoặc làm chủ các Trò chơi Kỹ năng."
    },
    {
      "id": "u11425",
      "vi": "Kiếm các ô PlayStyles"
    },
    {
      "id": "u38488",
      "vi": "Kết hợp linh hoạt các PlayStyles để tìm ra tổ hợp định hình phong cách của riêng bạn. Hoàn thiện kỹ năng bằng cách nâng cấp các Chỉ số và khai phá trọn vẹn tiềm năng của bản thân!"
    },
    {
      "id": "u40436",
      "vi": "Chọn Lối đi và Vươn tầm"
    },
    {
      "id": "u35116",
      "vi": "PlayStyles"
    },
    {
      "id": "u25556",
      "vi": "TIẾP TỤC ĐẾN HƯỚNG DẪN"
    },
    {
      "id": "u33808",
      "vi": "Archetype định hình sức mạnh, kỹ năng và khả năng của cầu thủ."
    },
    {
      "id": "u04852",
      "vi": "Chọn Archetype đầu tiên"
    },
    {
      "id": "u66607",
      "vi": "Bạn càng sử dụng Archetype nhiều, bạn càng có thể nâng cấp và tùy chỉnh nó sâu hơn."
    },
    {
      "id": "u20954",
      "vi": "Tạo dấu ấn riêng"
    },
    {
      "id": "u12709",
      "vi": "Bạn có thể linh hoạt mở khóa và chuyển đổi giữa nhiều Archetype khác nhau, nhưng bây giờ, hãy chọn cái đầu tiên nhé..."
    },
    {
      "id": "u45969",
      "vi": "Mở khóa tất cả"
    },
    {
      "id": "u38835",
      "vi": "Archetypes là các lớp cầu thủ độc đáo định hình phong cách chơi của bạn."
    },
    {
      "id": "u19010",
      "vi": "Định hình lối chơi của bạn bằng cách dùng AP để nâng cấp các Chỉ số."
    },
    {
      "id": "u22413",
      "vi": "Dùng Điểm Chỉ số"
    },
    {
      "id": "u55630",
      "vi": "Các Chỉ số Chính bổ trợ cho lối chơi của Archetype mà bạn đã chọn, giúp cầu thủ thi đấu hiệu quả hơn trên sân. Các chỉ số này sẽ tốn ít điểm nâng cấp hơn cho Archetype đó so với các chỉ số khác."
    },
    {
      "id": "u36394",
      "vi": "Chỉ số Chính"
    },
    {
      "id": "u36129",
      "vi": "Việc nâng cấp Chỉ số có thể mở khóa thêm PlayStyles & Kỹ năng Đặc biệt."
    },
    {
      "id": "u60411",
      "vi": "Mở khóa"
    },
    {
      "id": "u37247",
      "vi": "Nâng cấp Chỉ số"
    },
    {
      "id": "u33642",
      "vi": "Tùy chỉnh Archetype theo ý bạn!"
    },
    {
      "id": "u54030",
      "vi": "Lập đội cùng những người chơi khác trên toàn thế giới để tham gia thi đấu xếp hạng."
    },
    {
      "id": "u07516",
      "vi": "Drop-In"
    },
    {
      "id": "u69261",
      "vi": "Online Drop-In"
    },
    {
      "id": "u37972",
      "vi": "Tạo đội với bạn bè để thi đấu với những người chơi khác trong các trận đấu xếp hạng. Nhận thêm VC và XP khi chơi cùng bạn bè."
    },
    {
      "id": "u19101",
      "vi": "Lập đội"
    },
    {
      "id": "u35620",
      "vi": "Online Solo"
    },
    {
      "id": "u20244",
      "vi": "Sử dụng đội hình của riêng bạn và đối đầu với những người chơi khác trong các trận đấu xếp hạng đơn."
    },
    {
      "id": "u20679",
      "vi": "Chơi đơn"
    },
    {
      "id": "u41033",
      "vi": "Bàn thắng ghi bởi cầu thủ được chỉ định sẽ được tính là 2 điểm."
    },
    {
      "id": "u08970",
      "vi": "Điểm thưởng"
    },
    {
      "id": "u41171",
      "vi": "Hãy phối hợp đồng đội để tận dụng tối đa cầu thủ được chỉ định."
    },
    {
      "id": "u00452",
      "vi": "Cầu thủ được chỉ định sẽ thay đổi luân phiên trong suốt trận đấu."
    },
    {
      "id": "u38859",
      "vi": "Thay đổi luân phiên"
    },
    {
      "id": "u04528",
      "vi": "Cầu thủ Ghi bàn Chỉ định"
    },
    {
      "id": "u53280",
      "vi": "Đây không phải là một trận đấu thông thường - hãy vượt qua các điều kiện khắc nghiệt."
    },
    {
      "id": "u39926",
      "vi": "Đối mặt với các Điều kiện Khắc nghiệt"
    },
    {
      "id": "u17055",
      "vi": "Tất cả cầu thủ và trái bóng đều chịu ảnh hưởng bởi các điều kiện môi trường."
    },
    {
      "id": "u52719",
      "vi": "Hiệu ứng Thay đổi Trận đấu"
    },
    {
      "id": "u68983",
      "vi": "Các điều kiện không chỉ khắc nghiệt mà còn không thể đoán trước. Hãy cẩn thận!"
    },
    {
      "id": "u07291",
      "vi": "Điều kiện Khó lường"
    },
    {
      "id": "u68090",
      "vi": "Điều kiện Khắc nghiệt"
    },
    {
      "id": "u01327",
      "vi": "Giành chiến thắng trong những điều kiện khắc nghiệt nhất."
    },
    {
      "id": "u03005",
      "vi": "Thẻ Cơ sở vật chất cung cấp các điểm cộng chỉ số, Playstyles và Playstyles+ cho tất cả các cầu thủ do người chơi điều khiển trong các trận đấu League, Playoffs và Giao hữu."
    },
    {
      "id": "u34206",
      "vi": "Thẻ Cơ sở vật chất"
    }
  ]
}

{
  "translations": [
    {
      "id": "u43082",
      "vi": "Quản lý câu lạc bộ có thể phân bổ Ngân sách Cơ sở vật chất để kích hoạt Thẻ Cơ sở vật chất thay mặt cho câu lạc bộ. Ngân sách Cơ sở vật chất không bao giờ mất đi nên bạn cứ thoải mái thử nghiệm các tổ hợp khác nhau."
