{
  "translations": [
    {
      "id": "u10739",
      "vi": "Hoàn thành bài tập Jockey"
    },
    {
      "id": "u27874",
      "vi": "Hoàn thành bài tập Running Jockey"
    },
    {
      "id": "u58101",
      "vi": "Hoàn thành bài tập Contain"
    },
    {
      "id": "u55414",
      "vi": "Hoàn thành bài tập Teammate Contain"
    },
    {
      "id": "u13076",
      "vi": "Hoàn thành bài tập Push Pull"
    },
    {
      "id": "u01777",
      "vi": "Nhận XP Mùa giải bằng cách chơi các trận Volta Squads và Battles, hoặc tham gia Volta Arcade."
    },
    {
      "id": "u15408",
      "vi": "Chơi trận đấu"
    },
    {
      "id": "u40334",
      "vi": "Hoàn thành các Nhiệm vụ hàng tuần để tăng XP Mùa giải."
    },
    {
      "id": "u10641",
      "vi": "Hoàn thành Nhiệm vụ hàng tuần"
    },
    {
      "id": "u23579",
      "vi": "Nhận các phần thưởng mùa giải độc quyền — trang phục, phụ kiện độc đáo và hơn thế nữa — khi bạn lên cấp."
    },
    {
      "id": "u54280",
      "vi": "Nhận Phần thưởng Mùa giải"
    },
    {
      "id": "u45194",
      "vi": "Khám phá các môi trường, trang phục mới và nhiều nội dung khác trong các sự kiện này."
    },
    {
      "id": "u22390",
      "vi": "Các Mùa giải hoàn toàn mới!"
    },
    {
      "id": "u04790",
      "vi": "Thoát hướng dẫn"
    },
    {
      "id": "u09383",
      "vi": "Thử lại"
    },
    {
      "id": "u51326",
      "vi": "HƯỚNG DẪN"
    },
    {
      "id": "u04915",
      "vi": "Cố gắng áp sát bóng bằng ⟦1⟧. Khi đã ở vị trí thuận lợi, nhấn ⟦2⟧ để thực hiện tranh bóng."
    },
    {
      "id": "u37542",
      "vi": "Đuổi theo cầu thủ rê bóng bằng ⟦1⟧, và khi đã đủ gần để thực hiện xoạc bóng, hãy nhấn ⟦2⟧."
    },
    {
      "id": "u63498",
      "vi": "Để phòng ngự thành công trước cầu thủ rê bóng, bạn cần chọn vị trí tốt để tranh cướp. Giữ ⟦1⟧ để đối mặt với đối phương và kiểm soát tốc độ. Duy trì vị trí phòng ngự tốt giữa cầu thủ đối phương và khung thành trong 6 giây bằng kỹ thuật Jockey."
    },
    {
      "id": "u45386",
      "vi": "Khi cầu thủ đối phương di chuyển quá nhanh khiến bạn không thể theo kịp khi Jockey, hãy giữ cả ⟦1⟧ và ⟦2⟧ để Jockey với tốc độ cao hơn. Duy trì vị trí phòng ngự tốt giữa cầu thủ đối phương và khung thành trong 6 giây bằng kỹ thuật Running Jockey."
    },
    {
      "id": "u03077",
      "vi": "Giữ ⟦1⟧ để Contain cầu thủ đối phương. Khi thực hiện Contain, cầu thủ của bạn sẽ tự động Jockey đối phương ở khoảng cách vài mét. Bạn có thể thay đổi khoảng cách Jockey bằng cách di chuyển ⟦2⟧ về phía hoặc ra xa cầu thủ đối phương. Hãy Contain đối phương trong 6 giây để hoàn thành bài tập."
    },
    {
      "id": "u38791",
      "vi": "Giữ ⟦1⟧ để gọi đồng đội gây áp lực lên cầu thủ đối phương. Nếu giữ phím này trong khi cầu thủ bạn đang điều khiển cũng đang thực hiện Contain, đồng đội của bạn sẽ thực hiện Double cầu thủ đó. Hãy để đồng đội của bạn Contain đối phương trong 6 giây để hoàn thành bài tập."
    },
    {
      "id": "u65083",
      "vi": "Để kéo nhẹ đối phương khi đang đuổi theo, hoặc húc vai khi ở cạnh họ, hãy nhấn ⟦1⟧. Bạn có thể dùng kỹ thuật này để làm chậm đối phương, đuổi kịp họ hoặc khiến họ đỡ bước một lỗi. Tuy nhiên, nếu quá quyết liệt, trọng tài có thể thổi phạt."
    },
    {
      "id": "u49078",
      "vi": "Chọn từ nhiều loại trận đấu khác nhau, từ Rush đến các luật chơi tùy chỉnh, ví dụ như Mystery Ball."
    },
    {
      "id": "u11702",
      "vi": "Tạo Kick Off Name để theo dõi thành tích đối đầu và chỉ số của bạn với các đối thủ."
    },
    {
      "id": "u60655",
      "vi": "Theo dõi Chỉ số"
    },
    {
      "id": "u65387",
      "vi": "Sau khi đăng nhập, Kick Off Name và các chỉ số của bạn sẽ được liên kết chính thức với Tài khoản Mạng lưới Nền tảng của bạn."
    },
    {
      "id": "u35564",
      "vi": "Liên kết Kick Off Name với Tài khoản"
    },
    {
      "id": "u64456",
      "vi": "CHÀO MỪNG ĐẾN VỚI GIAO BÓNG"
    },
    {
      "id": "u35929",
      "vi": "Ba điều bạn cần biết"
    },
    {
      "id": "u27208",
      "vi": "Chọn một đội bóng và bắt đầu chế độ Sự nghiệp ngay lập tức, sử dụng các kết quả thực tế chính xác từ thế giới bóng đá."
    },
    {
      "id": "u02654",
      "vi": "Tải dữ liệu thực tế"
    },
    {
      "id": "u60267",
      "vi": "Tiếp quản đội bóng và hướng tới thành công ở các giải đấu mà đội của bạn tham gia."
    },
    {
      "id": "u17961",
