    },
    {
      "id": "u08437",
      "vi": "Bạn luôn có thể quay ngược thời gian và bắt đầu một hành trình mới từ bất kỳ thời điểm nào trong mùa giải."
    },
    {
      "id": "u43544",
      "vi": "Về đích mạnh mẽ"
    },
