    {
      "id": "u68969",
      "vi": "Giả lập đến ngày"
    },
    {
      "id": "u16254",
      "vi": "LỊCH THI ĐẤU"
    },
    {
      "id": "u34754",
      "vi": "Lịch thi đấu"
    },
    {
      "id": "u28177",
      "vi": "Kế hoạch phát triển"
    },
    {
      "id": "u22485",
      "vi": "Tốc độ phát triển phụ thuộc vào tần suất ra sân của cầu thủ, phong độ thi đấu, độ khó của giải đấu và Chất lượng lý tưởng của đội ngũ huấn luyện của bạn."
    },
    {
      "id": "u33218",
      "vi": "Phát triển vai trò"
    },
    {
      "id": "u59579",
      "vi": "Tốc độ phát triển"
    },
    {
      "id": "u40249",
      "vi": "KẾ HOẠCH PHÁT TRIỂN"
    },
    {
      "id": "u58652",
      "vi": "Đã đến lúc bắt đầu xây dựng đội ngũ huấn luyện của bạn.⟦1⟧⟦2⟧Chất lượng lý tưởng của đội ngũ huấn luyện phụ thuộc vào số lượng cầu thủ bạn có ở mỗi tuyến, cùng với chỉ số OVR và Tiềm năng của họ."
    },
    {
      "id": "u14698",
      "vi": "Kiến thức chiến thuật"
    },
    {
      "id": "u24955",
      "vi": "Huấn luyện viên có kiến thức sâu rộng nhất về Thiết lập chiến thuật của bạn sẽ được bổ nhiệm làm Huấn luyện viên trưởng."
    },
    {
      "id": "u08707",
      "vi": "Sức chứa nhân sự"
    },
    {
      "id": "u40900",
      "vi": "Các cầu thủ trẻ cũng sẽ được hưởng lợi từ đội ngũ huấn luyện."
    },
    {
      "id": "u46310",
      "vi": "Cứ sau hai tuần, Thị trường huấn luyện viên sẽ được làm mới dựa trên Tầm nhìn câu lạc bộ của bạn. Sức chứa nhân sự phụ thuộc vào giá trị câu lạc bộ và được cập nhật hàng năm."
    },
    {
      "id": "u41977",
      "vi": "THỰC THI TẦM NHÌN TRÊN SÂN CỎ"
    },
    {
      "id": "u37719",
      "vi": "Huấn luyện viên"
    },
    {
      "id": "u01785",
      "vi": "Thị trường huấn luyện viên là nơi bạn có thể xem các câu lạc bộ khác, Tầm nhìn chiến thuật mong muốn của họ và thêm họ vào danh sách theo dõi để nhận thông báo khi có vị trí trống."
    },
    {
      "id": "u67893",
      "vi": "An toàn công việc"
    },
    {
      "id": "u40307",
      "vi": "Danh tiếng của bạn với tư cách là huấn luyện viên, tình trạng của huấn luyện viên hiện tại tại câu lạc bộ đó và mức độ phù hợp giữa Tầm nhìn chiến thuật bạn thường dùng nhất với Tầm nhìn của câu lạc bộ mục tiêu sẽ quyết định khả năng bạn được tuyển dụng."
    },
    {
      "id": "u56531",
      "vi": "Độ tương thích công việc"
    },
    {
      "id": "u23601",
      "vi": "Hãy nhớ kiểm tra tab Gợi ý khi bạn đang tìm kiếm thử thách mới nhưng chưa có câu lạc bộ mục tiêu."
    },
    {
      "id": "u31727",
      "vi": "Huấn luyện viên tạm quyền"
    },
    {
      "id": "u22398",
      "vi": "Thị trường huấn luyện viên"
    },
    {
      "id": "u32089",
      "vi": "Tầm nhìn chiến thuật xác định cách tiếp cận chiến lược của đội bạn trong các trận đấu.⟦1⟧⟦2⟧Nó cũng sẽ tác động đến danh tiếng của bạn trên thế giới và có thể ảnh hưởng đến ý kiến của người hâm mộ, cũng như khả năng bạn được mời làm việc tại các câu lạc bộ khác."
