{
  "translations": [
    {
      "id": "u29050",
      "vi": "Tổng số Điểm Tính cách quyết định Bậc Tính cách của bạn. Bậc này quy định giá trị tăng cường chỉ số mà cầu thủ của bạn nhận được từ Tính cách của họ."
    },
    {
      "id": "u31038",
      "vi": "Bậc Tính cách"
    },
    {
      "id": "u43578",
      "vi": "Sự phân bổ điểm tính cách vào mỗi trong ba loại tính cách sẽ quyết định những chỉ số nào được tăng cường. Tính cách chiếm ưu thế sẽ tăng cường toàn bộ danh sách chỉ số liên quan."
    },
    {
      "id": "u56950",
      "vi": "Tăng cường chỉ số"
    },
    {
      "id": "u27437",
      "vi": "Tính cách"
    },
    {
      "id": "u35531",
      "vi": "Định hình hành trình của bạn bằng cách đàm phán với các Câu lạc bộ, cải thiện vị thế của bạn trong đội bóng hiện tại hoặc khám phá Con đường của bạn để tìm kiếm những cơ hội tốt hơn."
    },
    {
      "id": "u49808",
      "vi": "Tương lai trong tầm tay"
    },
    {
      "id": "u68244",
      "vi": "Vào cuối mỗi Mùa giải, phong độ của bạn sẽ được đánh giá và các Câu lạc bộ mà bạn đã đàm phán sẽ quyết định xem họ có muốn ký hợp đồng với bạn hay không."
    },
    {
      "id": "u45924",
      "vi": "Mùa giải mới, Khởi đầu mới"
    },
    {
      "id": "u20851",
      "vi": "Chỉ số tổng của Câu lạc bộ và kỳ vọng về lương của bạn quyết định mức độ khó của các nhiệm vụ. Việc hoàn thành chúng sẽ quyết định liệu Câu lạc bộ có muốn ký hợp đồng với bạn hay không."
    },
    {
      "id": "u20677",
      "vi": "Nhiệm vụ"
    },
    {
      "id": "u17095",
      "vi": "Người đại diện"
    },
    {
      "id": "u28818",
      "vi": "Người đại diện có thể giúp định hình sự nghiệp của bạn, miễn là bạn chứng minh được tham vọng bằng màn trình diễn trên sân cỏ."
    },
    {
      "id": "u18255",
      "vi": "Đàm phán với các Câu lạc bộ về Hợp đồng tiềm năng và xác định kỳ vọng về lương của bạn."
    },
    {
      "id": "u21515",
      "vi": "Đàm phán"
    },
    {
      "id": "u35008",
      "vi": "Yêu cầu hợp đồng"
    },
    {
      "id": "u37842",
      "vi": "Hoàn thành các Nhiệm vụ bắt buộc để đảm bảo một hợp đồng mới. Càng hoàn thành nhiều Nhiệm vụ, mức lương tiềm năng của bạn càng tăng. Nhưng đừng lo, nếu bạn không hoàn thành tất cả các nhiệm vụ, Câu lạc bộ vẫn có thể muốn ký hợp đồng với bạn."
    },
    {
      "id": "u36778",
      "vi": "Người đại diện - Nhiệm vụ"
    },
    {
      "id": "u45320",
      "vi": "Hoàn thành các Nhiệm vụ của người đại diện để chứng minh giá trị của bạn với các câu lạc bộ tiềm năng và chuẩn bị sẵn sàng cho các cuộc đàm phán."
    },
    {
      "id": "u18989",
      "vi": "Các đề xuất của Người đại diện"
    },
    {
      "id": "u25340",
      "vi": "Nhiệm vụ của Người đại diện"
    },
    {
      "id": "u34383",
      "vi": "Với tư cách là cầu thủ, bạn có thể làm theo đề xuất của người đại diện hoặc tự chọn câu lạc bộ mục tiêu mà bạn yêu thích và bắt đầu hành trình của mình."
    },
    {
      "id": "u49009",
      "vi": "Khi tiến xa hơn trong sự nghiệp, bạn sẽ được giới thiệu các câu lạc bộ bóng đá lớn hơn và uy tín hơn."
    },
    {
      "id": "u17892",
      "vi": "Công bố danh tiếng"
    },
    {
      "id": "u50028",
      "vi": "Người đại diện - Đề xuất"
    },
    {
      "id": "u53816",
      "vi": "Người đại diện sẽ đưa ra các đề xuất hướng tới tương lai của bạn, đảm bảo bạn tận dụng tối đa sự nghiệp của mình."
    },
    {
      "id": "u47301",
      "vi": "Người đại diện"
    },
    {
      "id": "u50894",
      "vi": "Khi chơi ở chế độ Cầu thủ, bạn sẽ kiểm soát bản thân để có thể tập trung 100% vào màn trình diễn cá nhân. Khi bạn nắm quyền kiểm soát toàn đội, hãy đảm bảo cầu thủ của bạn tham gia vào lối chơi."
    },
    {
      "id": "u62777",
      "vi": "Chơi một trận đấu"
    },
    {
      "id": "u14117",
      "vi": "Chơi qua tất cả các điểm nhấn của trận đấu hoặc chỉ chơi những tình huống liên quan đến cầu thủ của bạn. Hãy tận dụng tối đa từng điểm nhấn để đảm bảo đội của bạn giành chiến thắng."
    },
    {
      "id": "u63655",
      "vi": "Đi thẳng đến hồi còi mãn cuộc và xem kết quả trận đấu. Chỉ có nhiệm vụ Điểm số trận đấu của bạn mới được tính vào Sự tin tưởng của HLV."
    },
    {
      "id": "u24199",
      "vi": "Nhảy đến kết quả"
    },
    {
      "id": "u66554",
      "vi": "CHƠI TRẬN ĐẤU"
    },
    {
      "id": "u34700",
      "vi": "Có nhiều cách để chơi các trận đấu của bạn, hãy thử nghiệm chúng và chọn trải nghiệm mà bạn ưa thích."
    },
    {
      "id": "u29639",
      "vi": "Sử dụng Điểm chỉ số"
    },
    {
      "id": "u34116",
      "vi": "Nâng cấp Hình mẫu của bạn"
    },
    {
      "id": "u52142",
      "vi": "Các chỉ số bạn chọn phát triển sẽ giúp xác định phong cách chơi cá nhân của cầu thủ, cũng như khả năng đóng góp vào màn trình diễn của toàn đội trên sân cỏ."
    },
    {
      "id": "u58393",
      "vi": "Phát triển theo cách của bạn"
    },
    {
      "id": "u55233",
      "vi": "CHỈ SỐ"
    }
  ]
}

