{
  "translations": [
    {
      "id": "u02606",
      "vi": "Arsenal làm khách trên sân của nhà đương kim vô địch Manchester City trong trận cầu tâm điểm Super Sunday đầu mùa giải này, đây sẽ là thử thách khó khăn nhất đối với nhà đương kim vô địch tại Etihad tính đến thời điểm hiện tại của mùa giải. Mùa giải trước, cả hai trận đấu đều kết thúc với tỷ số 1-0 nghiêng về đội chủ nhà, và trận đấu hồi tháng Tư tại Emirates gần như đã giáng một đòn chí mạng vào hy vọng vô địch của Man City. Vì vậy, họ sẽ cần đảm bảo giành trọn ba điểm trong những cuộc đối đầu trực tiếp giữa các đội bóng hàng đầu để bảo vệ ngôi vương."
    },
    {
      "id": "u67272",
      "vi": "Manchester City đấu với Arsenal"
    },
    {
      "id": "u52722",
      "vi": "Thứ Bảy, ngày 23 tháng 9 năm 2012"
    },
    {
      "id": "u01227",
      "vi": "Manchester City"
    },
    {
      "id": "u51956",
      "vi": "Tạo ra nhiều cơ hội tấn công đột biến hơn với cơ chế tạt bóng hoàn toàn mới, mang đến cho người chơi đa dạng các kiểu tạt bóng vòng cung, tạt bóng nhanh và tạt tầm thấp từ hai biên."
    },
    {
      "id": "u29736",
      "vi": "Hệ thống chuyển động hoàn toàn mới mở ra một cấp độ nhạy bén và cá tính cầu thủ mới – giờ đây, Cristiano Ronaldo và các ngôi sao hàng đầu sẽ di chuyển và cảm nhận y hệt như trên sân cỏ thực tế."
    },
    {
      "id": "u47385",
      "vi": "Cơ chế rê bóng mới giúp tạo ra các pha chạm bóng rõ nét hơn, các cú xoay người chặt chẽ hơn và những pha chuyển trạng thái sang tấn công bùng nổ hơn bao giờ hết."
    },
    {
      "id": "u32508",
      "vi": "Khai phá tiềm năng của bạn với FC Trainer. Hãy học hỏi khi chơi với lớp phủ đồ họa tùy chọn, gợi ý cho bạn các lựa chọn chơi bóng dựa trên vị trí của bạn trên sân và cấp độ huấn luyện. Các lệnh cơ bản sẽ giúp bạn làm quen, trong khi các gợi ý chuyên sâu sẽ cải thiện kỹ năng của những người chơi lão luyện nhất."
    },
    {
      "id": "u20802",
      "vi": "Volta Football mang đến cho bạn trải nghiệm văn hóa, sự sáng tạo và phong cách đích thực của bóng đá đường phố. Tùy chỉnh và phát triển nhân vật của bạn, xây dựng đội hình, thách thức các ngôi sao và hợp tác với bạn bè để thi đấu với những người chơi khác ở khắp nơi trên thế giới. Volta Football sẽ có mặt trong FC 26."
    },
    {
      "id": "u56057",
      "vi": "TRÒ CHƠI CỦA THẾ GIỚI, ĐƯỢC TIẾP LỬA BỞI NHỮNG CẦU THỦ XUẤT SẮC NHẤT THẾ GIỚI"
    },
    {
      "id": "u65649",
      "vi": "KIỂM SOÁT TẠT BÓNG MỚI"
    },
    {
      "id": "u67461",
      "vi": "CÔNG NGHỆ CHUYỂN ĐỘNG CẦU THỦ THỰC TẾ"
    },
    {
      "id": "u57493",
      "vi": "CẢI TIẾN RÊ BÓNG"
    },
    {
      "id": "u23878",
      "vi": "MỤC TIÊU MÙA GIẢI"
    },
    {
      "id": "u21934",
      "vi": "UT FRIENDLIES"
    },
    {
      "id": "u07892",
      "vi": "ĐƯỢC VẬN HÀNH BỞI FROSTBITE™"
    },
    {
      "id": "u60280",
      "vi": "CẠNH TRANH Ở ĐẲNG CẤP CAO HƠN"
    },
    {
      "id": "u63462",
      "vi": "ĐỘI TUYỂN QUỐC GIA NỮ"
    },
    {
      "id": "u63342",
      "vi": "MỚI TRONG ⟦1⟧FOOTBALL ULTIMATE TEAM"
    },
    {
      "id": "u55127",
      "vi": "THE JOURNEY: HUNTER TRỞ LẠI"
    },
    {
      "id": "u63461",
      "vi": "FC TRAINER"
    },
    {
      "id": "u59240",
      "vi": "UEFA Champions League"
    },
    {
      "id": "u24118",
      "vi": "CÁC CÁCH CHƠI MỚI"
    },
    {
      "id": "u68984",
      "vi": "Tệp đội hình hiện tại không tương thích với bản demo. Vui lòng cài đặt lại bản demo mới nhất thông qua ứng dụng EA."
    },
    {
      "id": "u27153",
      "vi": "Tất cả 22 cầu thủ trên sân đều sở hữu trí thông minh để dự đoán và phản ứng theo bản năng với các tình huống xung quanh với thời gian phản ứng giống như con người, tương tự như các cầu thủ đẳng cấp thế giới."
    },
    {
      "id": "u10292",
      "vi": "BẢN NĂNG CHUYÊN NGHIỆP"
    },
    {
      "id": "u47576",
      "vi": "Với chiều sâu và chi tiết hoạt ảnh cao hơn, giờ đây các cầu thủ có thể trụ chân, xoay người, ngoặt bóng, thay đổi hướng và chuyển đổi động lượng với sự linh hoạt và bùng nổ của các vận động viên ưu tú."
    },
    {
      "id": "u54006",
      "vi": "CHUYỂN ĐỘNG CHÍNH XÁC"
    },
    {
      "id": "u41773",
      "vi": "THẾ GIỚI SỐNG ĐỘNG"
    },
    {
      "id": "u15731",
      "vi": "KỸ THUẬT ƯU TÚ"
    },
    {
      "id": "u70479",
      "vi": "Global Transfer Network là cách mới để trải nghiệm Chế độ Sự nghiệp với tư cách là huấn luyện viên. Giờ đây, bạn có thể cử đội ngũ tuyển trạch viên của mình đến các quốc gia khác nhau trên thế giới để tìm kiếm tài năng.⟦1⟧⟦2⟧Chỉ định loại cầu thủ bạn đang tìm kiếm bằng cách cung cấp một loạt các tiêu chí cho mạng lưới tuyển trạch dựa trên nhu cầu của đội bóng. Các tuyển trạch viên sẽ tìm kiếm trong các khu vực của họ những cầu thủ phù hợp với bất kỳ tiêu chí nào của bạn. Tuyển trạch viên giỏi hơn sẽ tốn nhiều tiền hơn để ký hợp đồng, nhưng họ sẽ cung cấp kết quả nghiên cứu nhanh hơn và thông tin chính xác hơn. Một cách khác để sử dụng mạng lưới là yêu cầu một trong những tuyển trạch viên của bạn xem xét một cầu thủ mà bạn đã nhắm tới nhưng cần thêm thông tin.⟦3⟧⟦4⟧Giờ đây, bạn đã sẵn sàng bắt đầu sự nghiệp huấn luyện viên của mình. Việc quản lý mạng lưới tuyển trạch và tìm kiếm tài năng mới sẽ đóng vai trò quan trọng đối với thành công của bạn tại câu lạc bộ. Hãy đảm bảo bạn luôn chỉ đạo họ trong suốt cả năm để chuẩn bị cho kỳ chuyển nhượng bận rộn."
    }
  ]
}

{
  "translations": [
    {
      "id": "u15497",
      "vi": "⟦1⟧ - Ném bóng / ⟦2⟧ + ⟦3⟧ - Ném bóng mạnh⟦4⟧⟦5⟧ - Phát bóng sống / ⟦6⟧ + ⟦7⟧ - Phát bóng mạnh"
    },
    {
      "id": "u05414",
      "vi": "⟦1⟧ - Chọc khe⟦2⟧⟦3⟧ - Sút bóng"
    },
    {
      "id": "u04643",
      "vi": "⟦1⟧ + ⟦2⟧ - Chuyền bóng chuẩn xác"
