    },
    {
      "id": "u26334",
      "vi": "⟦1⟧ + ⟦2⟧ + ⟦3⟧ - Đánh đầu chủ động"
    },
    {
      "id": "u64656",
      "vi": "⟦1⟧ + ⟦2⟧ - Phối hợp bật tường"
    },
    {
      "id": "u44604",
      "vi": "⟦1⟧ + ⟦2⟧ Khóa cầu thủ⟦3⟧Gạt cần ⟦4⟧ - Chuyển đổi cầu thủ"
    },
    {
      "id": "u02302",
      "vi": "• Sút bóng vào đối thủ để loại họ.⟦1⟧ • Càng trụ lại lâu, bạn càng ghi được nhiều điểm."
    },
    {
      "id": "u13602",
      "vi": "Rê bóng qua các cổng và Chip Shot qua đầu thủ môn.⟦1⟧Mẹo: Hãy đợi thủ môn rời xa khung thành để tăng cơ hội ghi bàn."
    },
    {
      "id": "u15900",
      "vi": "Giữ quyền kiểm soát bóng lâu nhất có thể trong khi đối thủ băng qua khu vực của bạn.⟦1⟧Mẹo: Tiếp cận gần đối thủ để nhận thêm điểm."
    },
    {
      "id": "u55566",
      "vi": "Thực hiện càng nhiều kỹ thuật khác nhau càng tốt trong khi ở trong khu vực di chuyển. Ghi bàn ở cuối bài tập.⟦1⟧Mẹo: Thực hiện kỹ thuật cạnh các hình nộm sẽ giúp bạn có thêm điểm."
    },
    {
      "id": "u24090",
      "vi": "Đợi cầu thủ vào đúng vị trí để thực hiện đường chuyền qua các cổng.⟦1⟧Mẹo: Sử dụng góc chuyền hẹp để thực hiện nhiều đường chuyền trong một lượt."
    },
    {
      "id": "u01335",
      "vi": "Sử dụng Rê bóng ngang để đi qua càng nhiều cổng càng tốt trong thời gian quy định.⟦1⟧Mẹo: Rê bóng ngang giúp bạn di chuyển chính xác hơn."
    },
    {
      "id": "u46972",
      "vi": "Vượt qua các hậu vệ bằng kỹ thuật, sau đó ghi bàn.⟦1⟧Mẹo: Hãy cố gắng canh thời điểm thực hiện kỹ thuật khi bạn vượt qua cổng ở cầu thủ cuối cùng."
    },
    {
      "id": "u01519",
      "vi": "Thực hiện thành công càng nhiều quả tạt càng tốt và ghi bàn để nhận thêm điểm.⟦1⟧Mẹo: Hãy cố gắng xoay người về phía đồng đội khi tạt bóng để giảm thiểu sai sót."
    },
    {
      "id": "u44575",
      "vi": "Chuyền bổng vào các khu vực hoạt động của cầu thủ. Càng gần tâm thì điểm càng cao.⟦1⟧Mẹo: Hãy cố gắng xoay người về phía cầu thủ mục tiêu để giảm thiểu sai sót khi chuyền bóng."
    },
    {
      "id": "u20135",
      "vi": "Chuyền bóng cho đồng đội mục tiêu trong khi tránh các hậu vệ.⟦1⟧Mẹo: Chuyền bóng cho các cầu thủ khác nếu đường chuyền tới mục tiêu bị hậu vệ chặn."
    },
    {
      "id": "u40358",
      "vi": "Thực hiện các đường chuyền bổng vào các khu vực được chỉ định. Khi vào vị trí, hãy tạt bóng cho người nhận trong vòng cấm.⟦1⟧Mẹo: Chọn vị trí chuẩn xác để thực hiện đường chuyền bổng với độ chính xác cao hơn."
    },
    {
      "id": "u08989",
      "vi": "Vượt qua hậu vệ và tạt bóng khi đang ở trong khu vực được đánh dấu. Khu vực này sẽ thay đổi vị trí sau mỗi lượt.⟦1⟧Mẹo: Rê bóng vào khoảng trống giữa bạn và hậu vệ trước khi tạt."
    },
    {
      "id": "u42790",
      "vi": "Sử dụng Thủ môn lao ra để ngăn cầu thủ tấn công sút bóng. Giành bóng trong khu vực được đánh dấu để nhận thêm điểm.⟦1⟧Mẹo: Hãy cố gắng canh thời điểm lao ra để chạm bóng ngay khi bóng đến khu vực đó."
    },
    {
      "id": "u54740",
      "vi": "Sử dụng Đồng đội áp sát hoặc Gây áp lực một phần để chặn các cú sút từ cầu thủ tấn công.⟦1⟧Mẹo: Hãy đứng giữa người chuyền và người sút để cắt bóng."
    },
    {
      "id": "u11571",
      "vi": "Ngăn các cú sút của đối thủ bay vào lưới.⟦1⟧Mẹo: Mũi tên chỉ hướng mà đối thủ của bạn sẽ sút."
    },
    {
      "id": "u12588",
      "vi": "Ngăn cầu thủ tấn công ghi bàn.⟦1⟧Mẹo: Chú ý kỹ các pha di chuyển của cầu thủ tấn công và đề phòng các đường chuyền vào phút chót."
    },
    {
      "id": "u35400",
      "vi": "• Mỗi quả bóng đều có bộ đếm thời gian hiển thị bên dưới.⟦1⟧ • Giữ quyền kiểm soát bóng khi bộ đếm thời gian này kết thúc để ghi điểm."
    },
    {
      "id": "u21439",
      "vi": "• Sút bóng vào bất kỳ ô nào của đối thủ.⟦1⟧• Nếu bóng nảy hai lần trong ô của bạn hoặc bạn sút bóng ra ngoài sân, bạn sẽ bị loại.⟦2⟧• Càng trụ lại lâu, bạn càng ghi được nhiều điểm."
    },
    {
      "id": "u09444",
      "vi": "Di chuyển cầu thủ của bạn quanh sân trong khi vẫn giữ quyền kiểm soát bóng."
    },
    {
      "id": "u37287",
      "vi": "Khi thực hiện phạt góc, hãy cố gắng đưa bóng vào vị trí mà các cầu thủ của bạn có khả năng tranh chấp thành công cao hơn."
    },
    {
      "id": "u05242",
      "vi": "Khi thực hiện đá phạt ở góc không thuận lợi hoặc ở khoảng cách xa khung thành, chuyền bóng cho đồng đội có thể là phương án tốt nhất."
    },
    {
      "id": "u39064",
      "vi": "Sử dụng chuyền bóng chuẩn xác khi bạn thấy cơ hội khai thác một khoảng trống cụ thể thay vì chuyền trực tiếp cho cầu thủ."
    }
  ]
}

{
  "translations": [
    {
      "id": "u08697",
      "vi": "Bạn là chốt chặn cuối cùng của đội; hãy khởi xướng đợt tấn công bằng cách chuyền bóng cho hậu vệ và sẵn sàng cản phá các cú sút từ đội bạn.⟦1⟧Mẹo: Chú ý di chuyển của đối phương và đề phòng những pha mất bóng bất ngờ. Mức hỗ trợ của thủ môn chịu ảnh hưởng bởi cài đặt Hỗ trợ Cản phá trong phần Cài đặt Trò chơi tại mục Thủ môn."
    },
    {
      "id": "u03532",
      "vi": "Lao về phía đối phương để cắt bóng.⟦1⟧Mẹo: Nếu tiền đạo nhanh hơn thủ môn, hãy cố gắng thu hẹp góc sút của đối phương. Mức hỗ trợ của thủ môn chịu ảnh hưởng bởi cài đặt Hỗ trợ Cản phá trong phần Cài đặt Trò chơi tại mục Thủ môn."
    },
    {
      "id": "u02741",
      "vi": "Đấm bóng từ quả tạt của đối phương để giải nguy và kết thúc đợt tấn công.⟦1⟧Mẹo: Căn thời gian bấm nút trùng với khoảnh khắc bóng chạm tay thủ môn để thực hiện cú đấm bóng hiệu quả nhất. Mức hỗ trợ của thủ môn chịu ảnh hưởng bởi cài đặt Hỗ trợ Cản phá trong phần Cài đặt Trò chơi tại mục Thủ môn."
    },
    {
      "id": "u14130",
      "vi": "Thực hiện các pha Chọc khe cho đồng đội được đánh dấu trong khi tránh các hậu vệ.⟦1⟧Mẹo: Luật việt vị được bật và sẽ có hiệu lực khi người nhận bóng đứng dưới hậu vệ cuối cùng tại thời điểm chuyền bóng."
    },
    {
      "id": "u18378",
      "vi": "Chuyền bóng cho đồng đội băng qua khu vực của hậu vệ.⟦1⟧Mẹo: Hãy chuyền bóng cho các cầu thủ ở phần sân nhà để tạo cơ hội nếu hướng chuyền bóng đến mục tiêu bị hậu vệ chặn mất."
    },
    {
      "id": "u22671",
      "vi": "Thực hiện các đường chuyền nhanh, liên tiếp cùng đồng đội để trở thành bậc thầy Tiki Taka. Hoàn thành các đường chuyền giữa những cầu thủ được đánh dấu để tạo thành hình tam giác và ghi nhiều điểm hơn.⟦1⟧Mẹo: Chuyền qua lại giữa hai cầu thủ để tạo khoảng trống mà không làm phá vỡ hình tam giác hiện tại của bạn."
    },
    {
      "id": "u01431",
      "vi": "Thực hiện các pha Chọc khe bổng cho đồng đội được chỉ định và ghi bàn để đạt số điểm cao nhất.⟦1⟧Mẹo: Luật việt vị được bật và sẽ có hiệu lực khi người nhận bóng đứng dưới hậu vệ cuối cùng tại thời điểm chuyền bóng."
    },
    {
      "id": "u06807",
      "vi": "Dốc bóng xuống biên và tạt vào \"Khu vực Nguy hiểm\" để ghi bàn. Luật việt vị không áp dụng trong thử thách này.⟦1⟧Mẹo: Hãy tạo khoảng trống bằng cách chuyền bóng cho tiền đạo thứ hai nếu bạn bị áp sát sau khi đỡ bóng từ quả tạt."
    },
    {
      "id": "u02144",
      "vi": "Chuyền bóng cho cầu thủ được đánh dấu và chuẩn bị tạt vào cho đồng đội trong vòng cấm. Ghi bàn để nhận thêm điểm.⟦1⟧Mẹo: Hãy cẩn thận với các chướng ngại vật và hậu vệ."
    },
    {
      "id": "u01357",
      "vi": "Thực hiện các pha Chuyền bổng vào các khu vực được chỉ định. Khi đã vào vị trí, hãy tạt bóng cho đồng đội trong vòng cấm.⟦1⟧Mẹo: Vị trí ban đầu tốt là yếu tố quan trọng để thực hiện pha Chuyền bổng chuẩn xác và hiệu quả."
    },
    {
      "id": "u33539",
      "vi": "Trải nghiệm nhiều tình huống ở cả vai trò tấn công và phòng ngự.⟦1⟧Mẹo: Hãy thử vận dụng các kỹ thuật đã học được trong những trò chơi kỹ năng khác để đạt số điểm cao nhất có thể."
    },
    {
      "id": "u03221",
      "vi": "Giành lại bóng trong khi gây sức ép lên hàng công đối phương.⟦1⟧Mẹo: Khép các góc tấn công bằng cầu thủ dư thừa."
    },
    {
      "id": "u00987",
      "vi": "Ghi càng nhiều bàn thắng càng tốt vào lưới thủ môn.⟦1⟧Mẹo: Tích lực cho cú sút để khiến thủ môn khó cản phá hơn."
    },
    {
      "id": "u00212",
      "vi": "Ghi càng nhiều bàn thắng càng tốt.⟦1⟧Mẹo: Hãy thử di chuyển tâm ngắm để thực hiện các cú sút Má ngoài hoặc Má trong vào góc cao khung thành."
    },
    {
      "id": "u03533",
      "vi": "Ghi càng nhiều bàn thắng càng tốt bằng cách đưa bóng cho đồng đội ở vị trí thuận lợi nhất.⟦1⟧Mẹo: Thêm độ xoáy cho cú sút và đưa bóng vòng qua các hậu vệ bằng cách thay đổi điểm tiếp xúc bóng của cầu thủ."
    },
    {
      "id": "u49488",
      "vi": "Ghi càng nhiều bàn thắng càng tốt bằng cách đưa bóng cho đồng đội ở vị trí thuận lợi nhất.⟦1⟧Mẹo: Thay đổi điểm tiếp xúc bóng và thêm độ xoáy."
    },
    {
      "id": "u05738",
      "vi": "Sút bóng qua các khe hở giữa các hình nộm. Đánh trúng mục tiêu để nhận thêm điểm.⟦1⟧Mẹo: Căn thời gian sút chuẩn xác sẽ giúp bạn giữ sự bình tĩnh và cải thiện độ chính xác."
    },
    {
      "id": "u06762",
      "vi": "Sút bóng qua các cổng được đánh dấu trong khi tìm cách ghi bàn. Tránh thủ môn.⟦1⟧Mẹo: Tính năng Sút Chính xác đã được bật, giúp việc nhắm mục tiêu chuẩn xác hơn."
    },
    {
      "id": "u07482",
      "vi": "Rê bóng qua các cổng và thực hiện cú sút Chip qua đầu thủ môn.⟦1⟧Mẹo: Hãy đợi thủ môn lao ra khỏi khung thành để tăng cơ hội ghi bàn của bạn."
    },
    {
      "id": "u02025",
      "vi": "Ghi càng nhiều bàn thắng càng tốt từ khu vực bên ngoài vòng cấm. Đánh trúng mục tiêu sẽ được thưởng thêm điểm.⟦1⟧Mẹo: Hãy luyện tập sút xoáy bằng cách tiếp cận khung thành theo một góc chéo phù hợp với chân thuận của cầu thủ và thực hiện cú sút Trivela."
    },
    {
      "id": "u01407",
      "vi": "Né tránh hậu vệ và nhận bóng từ 3 góc độ khác nhau để thực hiện các cú sút nhanh.⟦1⟧Mẹo: Hãy nhắm vào các mục tiêu để giành thêm điểm."
    },
    {
      "id": "u46086",
      "vi": "Né tránh hậu vệ và nhận bóng từ 3 góc độ khác nhau để thực hiện các cú sút nhanh.⟦1⟧Mẹo: Hãy nhắm vào các mục tiêu để giành thêm điểm."
    }
  ]
}

