    },
    {
      "id": "u49023",
      "vi": "Bạn có muốn tham gia lại cúp trong khung thời gian hiện tại không?"
    },
    {
      "id": "u63067",
      "vi": "Không thể tạo cúp vào lúc này. Vui lòng thử lại sau."
    },
    {
      "id": "u12450",
      "vi": "Thêm bạn bè để mời họ vào Club của bạn."
    },
    {
      "id": "u69791",
      "vi": "Đang tải thông tin Clubs..."
    },
    {
      "id": "u27034",
      "vi": "Bạn có chắc chắn muốn rời phiên trò chơi này không?"
    },
    {
      "id": "u63640",
      "vi": "Đồng đội của bạn đã rời Lobby."
    },
    {
      "id": "u07530",
      "vi": "Thêm bạn bè trong FC để cùng chơi và theo dõi lịch sử mùa giải của bạn trong Co-op Seasons."
    },
    {
      "id": "u18443",
      "vi": "Thêm bạn bè trong FC để cùng chơi và theo dõi lịch sử mùa giải của bạn trong Co-op Seasons.⟦1⟧⟦2⟧Để chơi cùng bạn bè trên các nền tảng khác, hãy thay đổi cài đặt Cross-play trong Cài đặt FC Online."
    },
    {
      "id": "u17197",
      "vi": "Có vẻ như đồng đội của bạn đã mất kết nối với trận đấu. Hãy thử gửi lại lời mời để tiếp tục chơi."
    },
    {
      "id": "u15026",
      "vi": "Khung thời gian giải đấu đã đóng."
    },
    {
      "id": "u59165",
      "vi": "Đang tải các thay đổi tùy chỉnh đã lưu cho đội hình trực tuyến và quản lý đội..."
    },
    {
      "id": "u27757",
      "vi": "Một tệp Đội hình trực tuyến mới đã được tải xuống và các tùy chỉnh trực tuyến đã được đặt lại."
    },
    {
      "id": "u61035",
      "vi": "Đang lưu các thay đổi tùy chỉnh cho đội hình trực tuyến và quản lý đội..."
    },
    {
      "id": "u60108",
      "vi": "Đang tải Lịch thi đấu trực tiếp"
    },
    {
      "id": "u63393",
      "vi": "Đang tải và áp dụng đội hình trực tuyến..."
    },
    {
      "id": "u35583",
      "vi": "Đang kiểm tra đội hình trực tuyến mới..."
    },
    {
      "id": "u56711",
      "vi": "Sẵn sàng tranh tài? Hãy thêm bạn bè trong FC và phân định thắng thua trong các trận giao hữu."
    },
    {
      "id": "u42538",
      "vi": "Sẵn sàng tranh tài? Hãy thêm bạn bè trong FC và phân định thắng thua trong các trận giao hữu.⟦1⟧⟦2⟧Để chơi cùng bạn bè trên các nền tảng khác, hãy thay đổi cài đặt Cross-play trong Cài đặt FC Online."
    },
    {
      "id": "u59801",
      "vi": "Bạn cần thêm người dùng này vào danh sách bạn bè trước khi tiếp tục."
    },
    {
      "id": "u61843",
      "vi": "Bắt đầu lại"
    },
    {
      "id": "u02247",
      "vi": "Đã xảy ra sự cố khi kiểm tra đội hình trực tuyến. Vui lòng thử lại sau."
    },
    {
      "id": "u35231",
      "vi": "Đang tải thông tin các mùa giải..."
    },
    {
      "id": "u10053",
      "vi": "Đang tải…"
    },
    {
      "id": "u64159",
      "vi": "Đang tải Chiến thuật"
    },
    {
      "id": "u21263",
      "vi": "Rất tiếc, khung thời gian cúp đã đóng. Vui lòng thử lại vào đợt mở tiếp theo."
    },
    {
      "id": "u15091",
      "vi": "Đã tìm thấy đối thủ..."
    },
    {
      "id": "u44390",
      "vi": "Có vẻ như kết nối với đối thủ của bạn đã bị mất. Hãy bắt đầu tìm kiếm lại. Để biết thêm thông tin, hãy truy cập ea.com/unable-to-connect."
    },
