{
  "translations": [
    {
      "id": "u03427",
      "vi": "Sử dụng mọi bộ phận trên cơ thể để ngăn chặn bóng bay vào lưới, với những pha cứu thua phản xạ xuất thần."
    },
    {
      "id": "u34825",
      "vi": "Thường được bố trí ở cánh đối diện với chân thuận, cầu thủ này luôn tìm cách bó vào trong để sút xa."
    },
    {
      "id": "u08299",
      "vi": "Tập trung vào việc đưa ra quyết định đột phá, dù là khi đối đầu với hậu vệ hay phối hợp cùng đồng đội."
    },
    {
      "id": "u32921",
      "vi": "Tiền đạo này chuyên dứt điểm một chạm đầy bản năng - dù bóng trên mặt đất hay trên không. Có khả năng tạo ra những điều không tưởng."
    },
    {
      "id": "u10620",
      "vi": "Một mục tiêu (Target) tối thượng! Cầu thủ làm tường cổ điển tận dụng tối đa thể hình để tranh chấp, cả trên mặt đất lẫn trên không."
    },
    {
      "id": "u44635",
      "vi": "Một thủ môn quét (Sweeper Keeper) tối thượng! Thủ môn hiện đại, thoải mái chơi bóng bằng chân và thường xuyên dâng cao hỗ trợ hàng phòng ngự."
    },
    {
      "id": "u04564",
      "vi": "Một trung vệ phát triển bóng (Progressor) tối thượng! Trung vệ hiện đại có khả năng dâng cao khỏi hàng thủ để bắt đầu các đợt tấn công bằng những đường chuyền tịnh tiến."
    },
    {
      "id": "u47036",
      "vi": "Một trung vệ thòng (sweeper) cực kỳ thoải mái khi kiểm soát bóng và thích dâng cao khỏi hàng thủ để thực hiện các đường chuyền."
    },
    {
      "id": "u40507",
      "vi": "Trang bị"
    },
    {
      "id": "u70073",
      "vi": "Không thể trang bị Specialization vào lúc này, vui lòng thử lại sau."
