    {
      "id": "u48741",
      "vi": "Thực hiện động tác giả trong vòng cấm để nhận được một khoảng thời gian ngắn tăng Lực Sút, Dứt điểm và Bình tĩnh."
    },
    {
      "id": "u60449",
      "vi": "Khi đối mặt 1 với 1 với Thủ môn, nhận được một khoảng thời gian ngắn tăng Kiểm soát bóng, Sự nhanh nhẹn và Thăng bằng."
    },
    {
      "id": "u01958",
      "vi": "Dẫn bóng ở tốc độ tối đa tại phần sân đối phương để nhận được một khoảng thời gian ngắn tăng Sự nhanh nhẹn, Thăng bằng và Phản xạ."
    },
    {
      "id": "u35672",
      "vi": "Thực hiện động tác giả để vượt qua đối thủ tại 1/3 sân đối phương để tăng Thăng bằng, Kiểm soát bóng và Rê bóng."
    },
    {
      "id": "u66234",
      "vi": "Thực hiện pha bật tường (Pass and Go) tại phần sân đối phương để nhận được một khoảng thời gian ngắn tăng Tăng tốc, Kiểm soát bóng và Thăng bằng."
    },
    {
      "id": "u46793",
      "vi": "Sút bóng sau khi xâm nhập vòng cấm từ cánh để nhận được một khoảng thời gian ngắn tăng Dứt điểm, Độ xoáy và Lực sút."
    },
    {
      "id": "u00913",
      "vi": "Tăng Bình tĩnh, Dứt điểm và Kiểm soát bóng cho đồng đội khi họ nhận đường chuyền của bạn trong vòng cấm."
    },
    {
      "id": "u36514",
      "vi": "Đẩy bóng vượt qua đối thủ ở hành lang cánh tấn công để tăng Tăng tốc, Sự nhanh nhẹn, Kiểm soát bóng."
    },
    {
      "id": "u66431",
      "vi": "Các đường chuyền sau khi xâm nhập vòng cấm từ cánh nhận được sự gia tăng về Chuyền ngắn, Tạt bóng và Nhãn quan."
    },
    {
      "id": "u46469",
      "vi": "Thực hiện Kỹ thuật vượt qua đối thủ ở hành lang cánh tấn công để tăng Sự nhanh nhẹn, Tăng tốc và Tốc độ chạy."
    },
    {
      "id": "u03796",
      "vi": "Thực hiện Kỹ thuật vượt qua đối thủ tại phần sân đối phương để tăng Chuyền ngắn, Độ xoáy và Bình tĩnh."
    },
    {
      "id": "u38272",
      "vi": "Thực hiện Kỹ thuật vượt qua đối thủ tại 1/3 sân đối phương để tăng Độ xoáy, Dứt điểm và Lực sút."
    },
    {
      "id": "u24072",
      "vi": "Sút bóng trong tư thế quay lưng về phía khung thành trong vòng cấm để nhận được một khoảng thời gian ngắn tăng Lực sút, Dứt điểm và Thăng bằng."
    },
    {
      "id": "u15654",
      "vi": "Các đường chuyền bổng (Dinked Passes) tại phần sân đối phương nhận được sự gia tăng về Kiểm soát bóng, Chuyền ngắn và Độ xoáy."
