    {
      "id": "u69116",
      "vi": "Là cầu thủ cuối cùng ở phần sân nhà để nhận buff cho Ý thức phòng ngự, Thăng bằng và Cắt bóng."
    },
    {
      "id": "u32348",
      "vi": "Thực hiện Slide Tackle thành công ở khu vực giữa sân để nhận buff ngắn hạn cho Bình tĩnh, Slide Tackle và Quyết đoán."
    },
    {
      "id": "u06032",
      "vi": "Nhận Chuyền bóng sệt ở phần sân nhà để nhận buff ngắn hạn cho Chuyền ngắn, Kiểm soát bóng và Tầm nhìn."
    },
    {
      "id": "u41674",
      "vi": "Áp sát người rê bóng trong vòng cấm để nhận buff ngắn hạn cho Tăng tốc, Quyết đoán và Phản xạ."
    },
    {
      "id": "u70765",
      "vi": "Thực hiện Hard Slide Tackle thành công ở 1/3 sân nhà để nhận buff cho Quyết đoán, Phản xạ và Sức mạnh."
    },
    {
      "id": "u34733",
      "vi": "Các đường Chuyền chuẩn xác ở phần sân nhà nhận buff ngắn hạn cho Độ xoáy, Chuyền dài và Sút bóng."
    },
    {
      "id": "u08193",
      "vi": "Giả sút để vượt qua đối thủ ở phần sân nhà để nhận buff cho Khéo léo, Thăng bằng và Kiểm soát bóng."
