    {
      "id": "u24902",
      "vi": "Tì đè đối thủ rồi sút trong vòng cấm để nhận buff cho Sức mạnh, Lực sút và Thăng bằng."
    },
    {
      "id": "u24154",
      "vi": "Chặn một cú Sút chìm để nhận buff ngắn hạn cho Khéo léo, Bắt bóng và Phản xạ."
    },
    {
      "id": "u20212",
      "vi": "Jockey khi người rê bóng ở 1/3 sân đối phương để nhận buff ngắn hạn cho Lao người, Thăng bằng và Phản xạ."
    },
    {
      "id": "u48827",
      "vi": "Cứu thua thành công để nhận buff ngắn hạn cho Phản xạ, Vị trí và Lao người."
